INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-6', 'cloudbridge-tech-insights-6', 'CloudBridge Industry Brief #6: Managed SIEM & Vulnerability Audit', 'تقرير كلاود بريدج التخصصي #6: مراقبة أمنية وفحص الثغرات', 'Key operational benchmarks and best practices from CloudBridge in Seef District.', 'أبرز المعايير التشغيلية وأفضل الممارسات من كلاود بريدج في Seef District.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations. Our Managed SIEM & Vulnerability Audit division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة. يساعد قسم مراقبة أمنية وفحص الثغرات المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>Bahraini software engineering and cloud MSP delivering Kubernetes platform engineering, SOC monitoring, and custom ERP integrations.</p><p>Our Managed SIEM & Vulnerability Audit division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>شركة هندسة برمجيات وخدمات سحابية تقدم حلول كوبيرنيتس والمراقبة الأمنية وتكامل الأنظمة.</p><p>يساعد قسم مراقبة أمنية وفحص الثغرات المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'it_software', '{"it_software","Seef District","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '54 days', false, now() - interval '54 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-6', 'Do you offer annual SLA retainers?', 'هل تتوفر عقود صيانة وتشغيل سنوية؟', 'Contact CloudBridge at hello@cloudbridge.bh or submit an inquiry online; our team responds within one business day.', 'يمكنكم التواصل عبر hello@cloudbridge.bh أو إرسال طلب إلكتروني وسيرد فريق كلاود بريدج خلال يوم عمل واحد.', 'general', true, 6, now()) ON CONFLICT (id) DO NOTHING;
